"use strict";
import { useQuery } from "@tanstack/react-query";
import { UniverseChainId } from "uniswap/src/features/chains/types";
const V2_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/v2-testnet/api";
const V3_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/aborean-finance-v3-abstract-testnet/api";
const ALL_V2_POOLS_QUERY = `
  query GetAllV2Pools {
    pairs(
      first: 1000
      orderBy: createdAtTimestamp
      orderDirection: desc
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      totalSupply
      stable
      volumeUSD
      untrackedVolumeUSD
      txCount
      createdAtTimestamp
      createdAtBlockNumber
    }
  }
`;
const ALL_V3_POOLS_QUERY = `
  query GetAllV3Pools {
    pools(
      first: 1000
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
      volumeUSD
      volumeToken0
      volumeToken1
      txCount
      createdAtTimestamp
      createdAtBlockNumber
      poolDayData(
        first: 30
        orderBy: date
        orderDirection: desc
      ) {
        id
        date
        volumeUSD
        volumeToken0
        volumeToken1
        tvlUSD
        txCount
        liquidity
      }
    }
  }
`;
async function fetchAllPoolsFromSubgraph() {
  try {
    const [v2Response, v3Response] = await Promise.all([
      fetch(V2_SUBGRAPH_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: ALL_V2_POOLS_QUERY })
      }).catch((error) => {
        console.warn("V2 subgraph fetch failed:", error);
        return null;
      }),
      fetch(V3_SUBGRAPH_URL, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: ALL_V3_POOLS_QUERY })
      }).catch((error) => {
        console.warn("V3 subgraph fetch failed:", error);
        return null;
      })
    ]);
    const v2Data = v2Response ? await v2Response.json().catch(() => null) : null;
    const v3Data = v3Response ? await v3Response.json().catch(() => null) : null;
    const v2Pools = v2Data?.data?.pairs || [];
    const v3Pools = v3Data?.data?.pools || [];
    if (v2Data?.errors) {
      console.warn("V2 subgraph returned errors:", v2Data.errors);
    }
    if (v3Data?.errors) {
      console.warn("V3 subgraph returned errors:", v3Data.errors);
    }
    return {
      v2Pools,
      v3Pools
    };
  } catch (error) {
    console.error("Failed to fetch pools from subgraph:", error);
    return { v2Pools: [], v3Pools: [] };
  }
}
export function useSharedPoolData(chainId = UniverseChainId.AbstractTestnet) {
  return useQuery({
    queryKey: ["shared-pool-data", chainId],
    queryFn: fetchAllPoolsFromSubgraph,
    staleTime: 6e4,
    // Consider data stale after 1 minute
    refetchInterval: 12e4,
    // Refetch every 2 minutes
    retry: (failureCount, error) => {
      if (error?.message?.includes("429") || error?.message?.includes("Too Many Requests")) {
        return failureCount < 2;
      }
      return failureCount < 3;
    },
    retryDelay: (attemptIndex) => {
      return Math.min(1e3 * 2 ** attemptIndex, 3e4);
    }
  });
}
export function useV2Pools(chainId) {
  const { data, isLoading, error } = useSharedPoolData(chainId);
  return {
    data: data?.v2Pools || [],
    isLoading,
    error
  };
}
export function useV3Pools(chainId) {
  const { data, isLoading, error } = useSharedPoolData(chainId);
  return {
    data: data?.v3Pools || [],
    isLoading,
    error
  };
}
